<?php
require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';api_v2_require_enabled();if($_SERVER['REQUEST_METHOD']!=='POST')api_v2_error('POST required',405);$in=api_input();$token=trim((string)($in['refresh_token']??''));if($token==='')api_v2_error('refresh_token required',422);$q=db()->prepare("SELECT r.*,u.name,u.email,u.phone,u.role,u.status FROM mobile_api_refresh_tokens r JOIN users u ON u.id=r.user_id WHERE r.token_hash=? AND r.revoked_at IS NULL AND r.expires_at>NOW() AND u.status='active' LIMIT 1");$q->execute([hash('sha256',$token)]);$r=$q->fetch();if(!$r)api_v2_error('Invalid or expired refresh token.',401);db()->beginTransaction();try{db()->prepare('UPDATE mobile_api_refresh_tokens SET revoked_at=NOW(),last_used_at=NOW() WHERE id=?')->execute([(int)$r['id']]);$user=['id'=>(int)$r['user_id'],'name'=>$r['name'],'email'=>$r['email'],'phone'=>$r['phone'],'role'=>$r['role']];$input=array_merge($in,['app_type'=>$r['app_type'],'device_id'=>$r['device_id']]);$auth=api_v2_issue_session($user,$input);db()->commit();api_v2_ok(['auth'=>$auth,'user'=>api_v2_user_public($user),'app_type'=>$r['app_type']],(int)$r['user_id']);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();api_v2_error('Unable to refresh session.',500);}
